create table if not exists public.irkop_cell_payroll_records (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.irkop_cell_businesses(id) on delete cascade, employee_name text not null, period date not null, base_amount numeric(14,2) not null default 0, bonus_amount numeric(14,2) not null default 0, deduction_amount numeric(14,2) not null default 0, paid_at timestamptz, notes text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists irkop_cell_payroll_business_period_idx on public.irkop_cell_payroll_records(business_id,period desc);
alter table public.irkop_cell_payroll_records enable row level security;
drop policy if exists "owners manage payroll" on public.irkop_cell_payroll_records;
create policy "owners manage payroll" on public.irkop_cell_payroll_records for all to authenticated using (exists(select 1 from public.irkop_cell_businesses b where b.id=business_id and b.owner_user_id=auth.uid())) with check (exists(select 1 from public.irkop_cell_businesses b where b.id=business_id and b.owner_user_id=auth.uid()));
do $$ declare b record; begin for b in select id from public.irkop_cell_businesses loop if not exists(select 1 from public.irkop_cell_payroll_records p where p.business_id=b.id) then insert into public.irkop_cell_payroll_records(business_id,employee_name,period,base_amount,bonus_amount,deduction_amount,notes) values(b.id,'Karyawan Demo',date_trunc('month',current_date)::date,3500000,250000,0,'Data awal demo V2'); end if; end loop; end $$;
